static void irq_entry(void *arg)
{
    (void)arg;
    g_raised++;
    g_fifo[g_tail++] = xTaskGetTickCountFromISR();
    g_lost_now = 0;
    echo_isr();
    if (g_lost_now > 1) {
        printf("FAIL: event_lost() called %u times for one echo\n", g_lost_now);
        g_errors++;
    }
    if (g_lost_now) {
        g_tail--;
        g_lost++;
    }
}

static void background_task(void *p)
{
    (void)p;
    for (;;) vSimBusyWork(1);
}

